      title: "Stay one step ahead",
      description: "Important work updates and reminders, without the noise.",
      badge: "SMART ALERTS",
      accentColor: "rgba(20, 90, 50, 0.35)",
      image: "https://images.unsplash.com/photo-1512428559087-560fa5ceab42?auto=format&fit=crop&w=800&q=80",
      floatingLabel: "REAL-TIME"
    },
    {
      number: "11",
      eyebrow: "SMART SEARCH",
      title: "Find anything instantly",
      description: "Search jobs, workers and payments without digging through lists.",
      badge: "FAST SEARCH",
      accentColor: "rgba(46, 125, 50, 0.35)",
      image: "https://images.unsplash.com/photo-1507238691740-187a5b1d37b8?auto=format&fit=crop&w=800&q=80",
      floatingLabel: "INSTANT FILTER"
    },
    {
      number: "12",
      eyebrow: "WORKSPACE",
      title: "Your workspace, your way",
      description: "Manage your business profile, preferences and account settings.",
      badge: "SETTINGS",
      accentColor: "rgba(107, 142, 35, 0.35)",
      image: "https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=800&q=80",
      floatingLabel: "CUSTOMIZABLE"
    }
  ];

  document.addEventListener("DOMContentLoaded", function() {
    initHeader();
    initMobileMenu();
    initShowcase();
    initKeyboardNav();
  });

  /* HEADER SCROLL BEHAVIOR */
  function initHeader() {
    const header = document.getElementById("wd-header");
    if (!header) return;

    window.addEventListener("scroll", function() {
      if (window.scrollY > 40) {
        header.classList.add("scrolled");
      } else {
        header.classList.remove("scrolled");
      }
    }, { passive: true });
  }

  /* MOBILE DRAWER TOGGLE */
  function initMobileMenu() {
    const toggleBtn = document.getElementById("wd-menu-toggle");
    const drawer = document.getElementById("wd-mobile-drawer");
    if (!toggleBtn || !drawer) return;

    toggleBtn.addEventListener("click", function() {
      const isOpen = drawer.classList.contains("open");
      if (isOpen) {
        drawer.classList.remove("open");
        toggleBtn.classList.remove("open");
        document.body.style.overflow = "";
      } else {
        drawer.classList.add("open");
        toggleBtn.classList.add("open");
        document.body.style.overflow = "hidden";
      }
    });

    const mobileLinks = drawer.querySelectorAll("a");
    mobileLinks.forEach(function(link) {
      link.addEventListener("click", function() {
        drawer.classList.remove("open");
        toggleBtn.classList.remove("open");
        document.body.style.overflow = "";
      });
    });
  }

  /* SHOWCASE EXPERIENCE & VERTICAL INDICATOR */
  function initShowcase() {
    const track = document.getElementById("wd-showcase-track");
    const viewport = document.getElementById("wd-showcase-viewport");
    const rail = document.getElementById("wd-indicator-rail");
    const currentNumEl = document.getElementById("wd-indicator-current");
    const totalNumEl = document.getElementById("wd-indicator-total");

    if (!track || !viewport || !rail) return;

    totalNumEl.textContent = String(workDailyScreens.length).padStart(2, '0');

    // Render Showcase Slides
    const variants = ["a", "b", "c", "d"];
    workDailyScreens.forEach(function(item, index) {
      const variant = variants[index % variants.length];
      const slide = document.createElement("div");
      slide.className = "wd-slide";
      slide.id = "wd-slide-" + index;
      slide.setAttribute("data-slide-index", index);

      const loadingAttr = index === 0 ? "eager" : "lazy";

      let compositionHTML = "";
      if (variant === "a" || variant === "d") {
        compositionHTML = `
          <div class="wd-slide-container wd-slide-variant-${variant}">
            <div class="wd-slide-text">
              <div class="wd-slide-eyebrow">
                <span class="wd-badge-dot"></span>
                <span>${item.eyebrow}</span>
              </div>
              <h2 class="wd-slide-title">${item.title}</h2>
              <p class="wd-slide-desc">${item.description}</p>
              <div class="wd-slide-badge">${item.badge}</div>
            </div>
            <div class="wd-slide-phone-wrap">
              <div class="wd-slide-phone">
                ${item.floatingLabel ? `<div class="wd-floating-badge wd-float-top-left">${item.floatingLabel}</div>` : ''}
                <img src="${item.image}" alt="${item.title}" class="wd-slide-img" loading="${loadingAttr}" decoding="async" />
              </div>
            </div>
          </div>
        `;
      } else {
        compositionHTML = `
          <div class="wd-slide-container wd-slide-variant-${variant}">
            <div class="wd-slide-text">
              <div class="wd-slide-eyebrow">
                <span class="wd-badge-dot"></span>
                <span>${item.eyebrow}</span>
              </div>
              <h2 class="wd-slide-title">${item.title}</h2>
              <p class="wd-slide-desc">${item.description}</p>
              <div class="wd-slide-badge">${item.badge}</div>
            </div>
            <div class="wd-slide-phone-wrap">
              <div class="wd-slide-phone">
                <img src="${item.image}" alt="${item.title}" class="wd-slide-img" loading="${loadingAttr}" decoding="async" />
              </div>
            </div>
          </div>
        `;
      }

      slide.innerHTML = `
        <div class="wd-slide-bg-glow" style="--slide-accent: ${item.accentColor};"></div>
        ${compositionHTML}
      `;

      track.appendChild(slide);
    });

    // Build Vertical Indicator Dots
    workDailyScreens.forEach(function(_, index) {
      const dot = document.createElement("button");
      dot.className = "wd-indicator-dot" + (index === 0 ? " active" : "");
      dot.setAttribute("aria-label", "Go to slide " + (index + 1));
      dot.addEventListener("click", function() {
        const targetSlide = document.getElementById("wd-slide-" + index);
        if (targetSlide) {
          targetSlide.scrollIntoView({ behavior: "smooth" });
        }
      });
      rail.appendChild(dot);
    });

    // IntersectionObserver to Track Active Slide
    const observerOptions = {
      root: viewport,
      threshold: 0.6
    };

    const observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          const idx = parseInt(entry.target.getAttribute("data-slide-index"), 10);
          updateActiveIndicator(idx);
          preloadAdjacentImages(idx);
        }
      });
    }, observerOptions);

    const slides = track.querySelectorAll(".wd-slide");
    slides.forEach(function(slide) {
      observer.observe(slide);
    });

    function updateActiveIndicator(activeIndex) {
      currentNumEl.textContent = String(activeIndex + 1).padStart(2, '0');
      const dots = rail.querySelectorAll(".wd-indicator-dot");
      dots.forEach(function(dot, i) {
        if (i === activeIndex) {
          dot.classList.add("active");
        } else {
          dot.classList.remove("active");
        }
      });
    }

    function preloadAdjacentImages(currentIndex) {
      const nextIndex = currentIndex + 1;
      if (nextIndex < workDailyScreens.length) {
        const img = new Image();
        img.src = workDailyScreens[nextIndex].image;
      }
    }
  }

  /* KEYBOARD NAVIGATION FOR SHOWCASE */
  function initKeyboardNav() {
    const viewport = document.getElementById("wd-showcase-viewport");
    if (!viewport) return;

    window.addEventListener("keydown", function(e) {
      // Only handle if showcase is currently in viewport view
      const rect = viewport.getBoundingClientRect();
      const inView = rect.top < window.innerHeight && rect.bottom > 0;
      if (!inView) return;

      if (e.key === "ArrowDown" || e.key === "PageDown") {
        viewport.scrollBy({ top: viewport.clientHeight, behavior: "smooth" });
      } else if (e.key === "ArrowUp" || e.key === "PageUp") {
        viewport.scrollBy({ top: -viewport.clientHeight, behavior: "smooth" });
      }
    });
  }
